export function ExitIntentModal({
  headline = "{{headline}}",
  offer = "{{offer}}",
  size = "{{size}}",
  accent = "{{accent}}",
  showDismiss = {{showDismiss}},
}) {
  const width = { compact: 240, standard: 340, large: 460 }[size] ?? 340;
  return (
    <div style={{ background: "#24143099", padding: "40px 20px", display: "flex", justifyContent: "center", borderRadius: 12 }}>
      <div role="dialog" aria-modal="true" aria-labelledby="exit-r-title" style={{ position: "relative", width,
        background: "#FAF7F2", borderRadius: 16, padding: size === "large" ? 36 : size === "compact" ? 20 : 28,
        textAlign: "center", font: "16px/1.5 system-ui, sans-serif", color: "#241430", boxShadow: "0 20px 48px rgba(0,0,0,.3)" }}>
        <button type="button" aria-label="Close dialog" style={{ position: "absolute", top: 8, right: 8, background: "none",
          border: "none", fontSize: 20, cursor: "pointer", color: "#241430aa" }}>&times;</button>
        <h2 id="exit-r-title" style={{ margin: "0 0 10px", fontSize: 22, fontWeight: 800 }}>{headline}</h2>
        <p style={{ margin: "0 0 20px", color: "#241430cc" }}>{offer}</p>
        <button type="button" style={{ display: "block", width: "100%", border: "none", color: "#FAF7F2", padding: 12,
          borderRadius: 10, fontWeight: 700, cursor: "pointer", background: accent }}>Claim offer</button>
        {showDismiss && <a href="#" style={{ display: "inline-block", marginTop: 14, fontSize: 13, color: "#241430aa", textDecoration: "underline" }}>No thanks</a>}
      </div>
    </div>
  );
}
